// MIT. Removes this program only; the separate archive is always retained.
using System;using System.IO;using System.Diagnostics;using System.Reflection;using System.Threading;using System.Windows.Forms;using Microsoft.Win32;
class DisinstallaRadici {
 static string ProgramRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Programs","Radici");
 static void Validate(string root){if(!Path.GetFullPath(root).TrimEnd('\\').Equals(Path.GetFullPath(ProgramRoot).TrimEnd('\\'),StringComparison.OrdinalIgnoreCase)||!File.Exists(Path.Combine(root,"radici-desktop-install.json")))throw new IOException("La cartella non è l’installazione Radici prevista.");string data=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Radici","Archivio");if(Directory.Exists(Path.Combine(root,"Dati")))throw new IOException("Nella cartella programma sono presenti dati: rimozione interrotta per conservarli.");string path=root;while(path!=null){if(Directory.Exists(path)&&(File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("Il percorso contiene un collegamento speciale.");path=Path.GetDirectoryName(path);}string lockFile=Path.Combine(data,"Impostazioni/radici.lock");if(File.Exists(lockFile))using(var file=new FileStream(lockFile,FileMode.Open,FileAccess.Read,FileShare.None)){} }
 [STAThread]static int Main(string[] args){Application.EnableVisualStyles();try{if(args.Length==2&&args[0]=="--remove-root"){Validate(args[1]);Thread.Sleep(750);Directory.Delete(args[1],true);string menu=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"Radici");foreach(string file in new[]{Path.Combine(menu,"Radici.lnk"),Path.Combine(menu,"Disinstalla Radici.lnk"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),"Radici.lnk")})if(File.Exists(file))File.Delete(file);if(Directory.Exists(menu)&&Directory.GetFileSystemEntries(menu).Length==0)Directory.Delete(menu);using(var parent=Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Uninstall",true))if(parent!=null)parent.DeleteSubKeyTree("RadiciDesktop",false);MessageBox.Show("Radici è stato disinstallato. Alberi, foto, stampe e backup rimangono sul PC nella cartella Radici\\Archivio del tuo profilo.","Radici");return 0;}
 Validate(ProgramRoot);if(MessageBox.Show("Disinstallare il programma Radici?\n\nAlberi, foto, stampe e backup rimarranno conservati sul PC.","Disinstalla Radici",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return 0;
 string temp=Path.Combine(Path.GetTempPath(),"DisinstallaRadici-"+Guid.NewGuid().ToString("N")+".exe");File.Copy(Assembly.GetExecutingAssembly().Location,temp);Process.Start(new ProcessStartInfo(temp,"--remove-root \""+ProgramRoot+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});return 0;
 }catch(Exception error){MessageBox.Show("Rimozione non completata. Chiudi Radici e riprova. "+error.Message,"Radici");return 1;}}
}
